package de.yaacc.fcast.protocol;

import java.util.HashMap;
import java.util.Map;

/**
 * Messages of FCast protocol v4 as the <b>reference implementation</b> writes them (the Rust crate {@code fcast-protocol} 0.2.0 of
 * <a href="https://github.com/futo-org/fcast">the FCast repository</a> at commit {@code ea3982b3}, {@code v4::MessageBuilder}, made by
 * a scratch program on 2026-11-22). The bodies of {@code Flatbuf} packets, as hex. The hand-written readers must understand them and the
 * hand-written builders must make buffers that the reference reads (checked once with a Rust reader, see docs/tech.md).
 */
public final class V4Golden {
    private static final Map<String, byte[]> BUFFERS = new HashMap<>();

    static {
        BUFFERS.put("senderIntroduction",
                hex("0c00000008000e000700080008000000000000060c000000000006000a000400060000001000000000000a001000040008000c000a00000028000000140000000400000005000000312e322e3300000009000000594141434320617070000000050000005941414343000000"));
        BUFFERS.put("loadFull",
                hex(""));
        BUFFERS.put("loadMinimal",
                hex("04000000f4ffffff000000010c00000008000c000700080008000000000000010c00000008000c0004000800080000001c000000040000000e000000687474703a2f2f682f612e6d703300000a000000617564696f2f6d7065670000"));
        BUFFERS.put("loadQueue",
                hex(""));
        BUFFERS.put("progress",
                hex("100000000000000008000c000700080008000000000000020c0000000800140004000c000800000060e316000000000040c9a20300000000"));
        BUFFERS.put("progressZero",
                hex("100000000000000008000c000700080008000000000000020c0000000800140004000c000800000000000000000000000000000000000000"));
        BUFFERS.put("volume",
                hex("0c00000008000e000700080008000000000000030c0000000000060008000400060000000000003f"));
        BUFFERS.put("volumeZero",
                hex("0c00000008000c00070008000800000000000003080000000400040004000000"));
        BUFFERS.put("speed",
                hex("0c00000008000e000700080008000000000000050c0000000000060008000400060000000000a03f"));
        BUFFERS.put("stateIdle",
                hex("0c00000008000c00070008000800000000000004080000000400040004000000"));
        BUFFERS.put("stateBuffering",
                hex("0c00000008000e000700080008000000000000040c00000000000600080007000600000000000001"));
        BUFFERS.put("statePlaying",
                hex("0c00000008000e000700080008000000000000040c00000000000600080007000600000000000002"));
        BUFFERS.put("statePaused",
                hex("0c00000008000e000700080008000000000000040c00000000000600080007000600000000000003"));
        BUFFERS.put("stateEnded",
                hex("0c00000008000e000700080008000000000000040c00000000000600080007000600000000000004"));
        BUFFERS.put("stop",
                hex("0c00000008000c00070008000800000000000008080000000400040004000000"));
        BUFFERS.put("error",
                hex("04000000f4ffffff000000170c00000008000c0007000800080000000000000507000000"));
        BUFFERS.put("errorNoNumber",
                hex("0c00000008000e000700080008000000000000170c0000000000060008000700060000000000000c"));
        BUFFERS.put("receiverIntroduction",
                hex(""));
        BUFFERS.put("tracks",
                hex(""));
        BUFFERS.put("changeTrack",
                hex("0c00000008000c0007000800080000000000000e0c00000008000c0008000700080000000000000103000000"));
        BUFFERS.put("changeTrackOff",
                hex("0c00000008000c0007000800080000000000000e0c00000008000800000007000800000000000002"));
        BUFFERS.put("addSubtitle",
                hex("0c00000008000e000700080008000000000000101000000000000a001000080007000c000a00000000000001200000000400000012000000456e676c697368202865787465726e616c2900000e000000687474703a2f2f682f612e7372740000"));
        BUFFERS.put("addSubtitleNoName",
                hex("0c00000008000e000700080008000000000000100c000000000006000800040006000000040000000e000000687474703a2f2f682f622e7674740000"));
        BUFFERS.put("progressInterval",
                hex("100000000000000008000e000700080008000000000000110c000000000006000c0004000600000040420f0000000000"));
    }

    private V4Golden() {
    }

    /** The reference's buffer of that name. */
    public static byte[] get(String name) {
        byte[] buffer = BUFFERS.get(name);
        if (buffer == null) {
            throw new IllegalArgumentException("no golden buffer " + name);
        }
        return buffer.clone();
    }

    public static byte[] hex(String text) {
        byte[] bytes = new byte[text.length() / 2];
        for (int i = 0; i < bytes.length; i++) {
            bytes[i] = (byte) Integer.parseInt(text.substring(2 * i, 2 * i + 2), 16);
        }
        return bytes;
    }
}
